import { boot } from 'quasar/wrappers';
import * as Sentry from '@sentry/vue';
import { safeBoot } from 'src/utils/bootSafety';

const SENTRY_IGNORED_ERROR_PATTERNS = [
  /ResizeObserver/i,
  /chrome-extension:\/\//i,
  /moz-extension:\/\//i,
  /localhost:\d+/i,
  /127\.0\.0\.1:\d+/i,
  /Failed to fetch dynamically imported module/i,
  /error loading dynamically imported module/i,
  /Loading chunk \d+ failed/i,
  /Importing a module script failed/i,
  /Failed to execute 'importScripts'/i,
  /Couldn't resolve component "default"/i,
  /\bNetwork Error\b/i,
  /\bNetwork connection failed\b/i,
  /\bDevice is offline\b/i,
  /\bRequest aborted\b/i,
  /\bAbortError\b/i,
  /Object captured as (promise rejection|exception) with keys: .*success/i,
  /Object captured as (promise rejection|exception) with keys: (message|detail)\b/i,
];

function collectSentryEventText(event: any, hint?: any): string {
  const parts: string[] = [];

  if (event?.message) parts.push(String(event.message));
  if (event?.request?.url) parts.push(String(event.request.url));

  for (const exception of event?.exception?.values ?? []) {
    if (exception?.type) parts.push(String(exception.type));
    if (exception?.value) parts.push(String(exception.value));

    for (const frame of exception?.stacktrace?.frames ?? []) {
      if (frame?.filename) parts.push(String(frame.filename));
      if (frame?.function) parts.push(String(frame.function));
    }
  }

  const original = hint?.originalException;
  if (original) {
    if (typeof original === 'string') {
      parts.push(original);
    } else {
      if (original.message) parts.push(String(original.message));
      if (original.stack) parts.push(String(original.stack));
      if ('success' in original)
        parts.push(`success:${String(original.success)}`);
      if ('error_code' in original) parts.push(String(original.error_code));
    }
  }

  const serialized = event?.extra?.__serialized__;
  if (serialized && typeof serialized === 'object') {
    if ('success' in serialized) {
      parts.push(`success:${String(serialized.success)}`);
    }
    if ('message' in serialized) {
      parts.push(String(serialized.message));
    }
    if ('error_code' in serialized) {
      parts.push(String(serialized.error_code));
    }
  }

  return parts.join('\n');
}

export function shouldDropSentryEvent(event: any, hint?: any): boolean {
  const text = collectSentryEventText(event, hint);
  if (SENTRY_IGNORED_ERROR_PATTERNS.some((pattern) => pattern.test(text))) {
    return true;
  }

  if (
    /Element not found/i.test(text) &&
    /(apexcharts|vue3-apexcharts|\/charts-[\w-]+\.js)/i.test(text)
  ) {
    return true;
  }

  const serialized = event?.extra?.__serialized__ ?? hint?.originalException;
  if (
    serialized &&
    typeof serialized === 'object' &&
    serialized.success === false
  ) {
    return true;
  }

  return false;
}

export function isLocalSentryHost(hostname: string | undefined): boolean {
  return (
    hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '::1'
  );
}

export default boot(
  safeBoot('sentry', ({ app, router }) => {
    // Sentry is disabled by default; enable via SENTRY_ENABLED=true in .env
    const enabled = process.env.SENTRY_ENABLED === 'true';
    const dsn = process.env.SENTRY_DSN || '';
    const tracesSampleRate = parseFloat(
      process.env.SENTRY_TRACES_SAMPLE_RATE || '0.1',
    );

    const hostname =
      typeof window !== 'undefined' ? window.location.hostname : undefined;
    if (
      !enabled ||
      !dsn ||
      process.env.APP_VUE_STAGE === 'local' ||
      isLocalSentryHost(hostname)
    ) {
      return;
    }

    Sentry.init({
      app,
      dsn,
      integrations: [
        Sentry.browserTracingIntegration({ router }),
        Sentry.replayIntegration(),
      ],

      // Performance Monitoring
      tracesSampleRate,

      // Session Replay
      replaysSessionSampleRate: 0.1, // Sample 10% of sessions
      replaysOnErrorSampleRate: 1.0, // Sample 100% of sessions with errors

      beforeSend(event, hint) {
        return shouldDropSentryEvent(event, hint) ? null : event;
      },
    });
  }),
);
